        odd = walsh_hadamard_transform([f[i] for i in range(1, len(f), 2)], n // 2)
        return [even[i] + odd[i] for i in range(n // 2)] + [even[i] - odd[i] for i in range(n // 2)]

    def k_clique_indicator(n, k):
